Method.Source:
/// <summary>
/// N.Freidenberger 25.04.4025
/// </summary>
/// <param name = "_curBOMBatch">_curBOMBatch</param>
/// <returns>parmCurBOMBatch</returns>
public Batch parmCurBOMBatch(Batch _curBOMBatch = curBOMBatch)
{
    curBOMBatch = _curBOMBatch;

    return curBOMBatch;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_avacostModelCombination">_avacostModelCombination</param>
/// <returns>AVACostModelCombination</returns>
AVACostModelCombination         parmAVACostModelCombination(AVACostModelCombination         _avacostModelCombination = avaCostModelCombination)
{
    AVABomCalcParameter     bomCalcParameter;

    select firstonly    bomCalcParameter
        where bomCalcParameter.UserId == curUserId();
    return bomCalcParameter.AVACostModelCombination;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>BOMclacItem</returns>
protected BOMCalcItem constructBOMCalcItem()
{
    BOMCalcItem     bomCalcItem = next constructBOMCalcItem();
    bomCalcItem.parmAVACostModelCombination(this.parmAVACostModelCombination());
    return bomCalcItem;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>qty</returns>
public Qty seriesSize()
{
    Qty seriesSize = next seriesSize();
    CostingVersion      costingVersion = CostingVersion::find(versionId);
    if (costingVersion.AVAUseStandardCalcQty)
    {
        seriesSize = costingVersion.AVAStandardCalculateQty;
    }
    return seriesSize;
}
